void alexnet_forward(const float* x, /*all conv/fc params*/, float* out){
  conv_relu_pool(x, conv1_w, conv1_b, tmp1, ...);
  conv_relu_pool(tmp1, conv2_w, conv2_b, tmp2, ...);
  conv_relu(tmp2, conv3_w, conv3_b, tmp3, ...);
  conv_relu(tmp3, conv4_w, conv4_b, tmp4, ...);
  conv_relu_pool(tmp4, conv5_w, conv5_b, tmp5, ...);
  flatten(tmp5, flat);
  linear_relu(flat, fc1_w, fc1_b, tmp6);
  linear_relu(tmp6, fc2_w, fc2_b, tmp7);
  linear(tmp7, fc3_w, fc3_b, out);
}

void vgg16_forward(const float* x, /*params*/, float* out){
  // Sequential conv-bn-relu blocks
  conv_bn_relu(x, c1_w, c1_b, t1, ...);
  conv_bn_relu(t1, c2_w, c2_b, t2, ...);
  maxpool(t2, p1, ...);
  /* repeat sets of conv_bn_relu and pool */
  flatten(p5, flat);
  linear_relu(flat, fc1_w, fc1_b, tmp);
  linear_relu(tmp, fc2_w, fc2_b, tmp2);
  linear(tmp2, fc3_w, fc3_b, out);
}

void mobilenet_block(const float* x, const float* dw_w, const float* pw_w, /*bn params*/, float* out, int N, int C, int H, int W){
  depthwise_conv_kernel(x, dw_w, dw_out, N,C,H,W,...);
  batchnorm_kernel(dw_out, bn1_mean,bn1_var,bn1_gamma,bn1_beta,...);
  relu6_kernel(dw_out, act1_out,...);
  pointwise_conv_kernel(act1_out, pw_w, pw_out,...);
  batchnorm_kernel(pw_out, bn2_mean,bn2_var,bn2_gamma,bn2_beta,...);
  relu6_kernel(pw_out, out,...);
}

void minigpt_block(const float* x, /*attn params*/, /*mlp params*/, float* out, int B, int S, int D){
  layernorm_kernel(x, ln1_gamma, ln1_beta, norm1_out,...);
  mha_kernel(norm1_out, mha_wq,mha_wk,mha_wv,mha_wo, attn_out,...);
  add_kernel(x, attn_out, res1_out, B*S*D);
  layernorm_kernel(res1_out, ln2_gamma, ln2_beta, norm2_out,...);
  ffn_kernel(norm2_out, ffn_w1, ffn_b1, ffn_w2, ffn_b2, ffn_out,...);
  add_kernel(res1_out, ffn_out, out, B*S*D);
}

void mamba_block(const float* x, /*SSM params*/, /*mlp params*/, float* out, int B, int L, int H){
  layernorm_kernel(x, ln1_gamma, ln1_beta, norm1,...);
  ssm_scan_kernel(norm1, ssm_params, ssm_out, B,L,H,...);
  gated_mlp_kernel(ssm_out, mlp_w1, mlp_b1, mlp_w2, mlp_b2, mlp_out,...);
  add_kernel(x, mlp_out, out, B*L*H);
}

void bert_encoder_block(const int* input_ids, const float* emb_w, const float* pos_enc, /*attn params*/, /*ffn params*/, float* out, int B, int L, int H){
  embedding_lookup_kernel(input_ids, emb_w, emb_out, B,L,H,...);
  add_kernel(emb_out, pos_enc, emb_pe_out, B*L*H);
  layernorm_kernel(emb_pe_out, ln1_gamma, ln1_beta, norm1,...);
  mha_kernel(norm1, attn_wq,attn_wk,attn_wv,attn_wo, attn_out,...);
  add_kernel(emb_pe_out, attn_out, res1,...);
  layernorm_kernel(res1, ln2_gamma, ln2_beta, norm2,...);
  ffn_kernel(norm2, ffn_w1,ffn_b1,ffn_w2,ffn_b2, ffn_out,...);
  add_kernel(res1, ffn_out, out, B*L*H);
}

void gpt2_decoder_block(const int* input_ids, const float* emb_w, /*attn params*/, /*ffn params*/, float* out, int B, int L, int H){
  embedding_lookup_kernel(input_ids, emb_w, emb_out,...);
  layernorm_kernel(emb_out, ln1_gamma, ln1_beta, norm1,...);
  causal_mha_kernel(norm1, attn_wq,attn_wk,attn_wv,attn_wo, attn_out,...);
  add_kernel(emb_out, attn_out, res1,...);
  layernorm_kernel(res1, ln2_gamma, ln2_beta, norm2,...);
  ffn_kernel(norm2, ffn_w1,ffn_b1,ffn_w2,ffn_b2, ffn_out,...);
  add_kernel(res1, ffn_out, out,...);
}

void resnet50_bottleneck_block(const float* x, /*conv params*/, float* out, int N, int C, int H, int W){
  conv_bn_relu(x, w1,b1, t1,...);
  conv_bn_relu(t1, w2,b2, t2,...);
  conv_bn(t2, w3,b3, t3,...);
  if(use_proj) conv_bn(x, proj_w,proj_b, skip,...);
  add_kernel(t3, skip, sum,...);
  relu_kernel(sum, out,...);
}

void efficientnet_mbconv_block(const float* x, /*expand params*/, /*dw params*/, /*se params*/, /*project params*/, float* out, int N, int C, int H, int W){
  conv1x1(x, expand_w, expand_b, t1,...);
  batchnorm_kernel(t1,...);
  swish_kernel(t1, t2,...);
  depthwise_conv_kernel(t2, dw_w, dw_out,...);
  batchnorm_kernel(dw_out,...);
  se_kernel(dw_out, se_w1,se_b1,se_w2,se_b2, se_out,...);
  swish_kernel(se_out, se_act,...);
  conv1x1(se_act, project_w, project_b, t3,...);
  batchnorm_kernel(t3,...);
  if(use_res) add_kernel(x, t3, out,...); else memcpy(t3,out,...);
}
